differential_test!(
    diff_empty_statement,
    "DiffEmptyStatement",
    r#"
public class DiffEmptyStatement {
    public static void main(String[] args) {
        // A stray `;` is an empty statement (JLS 14.6), not an error, and it
        // must not swallow the statement after it.
        int total = 0;
        for (int i = 0; i < 3; i++) {
            int x = i + 1;;
            total += x;
        }
        System.out.println(total);

        int y = 5;;
        System.out.println(y);

        ;
        System.out.println("after a lone semicolon");

        ;;;
        System.out.println("after three");

        if (total > 0) {
            ;
            System.out.println("inside if");
        }

        // The already-correct positions: an embedded empty statement is an
        // empty block, and a switch arm tolerates one too.
        for (int i = 0; i < 0; i++);
        switch (y) {
            case 5:
                ;
                System.out.println("case 5");
                break;
            default:
                break;
        }

        int count = 0;
        do { count++;; } while (count < 2);
        System.out.println(count);
    }
}
"#
);

differential_test_stdin!(
    diff_scanner_close_closes_standard_in,
    "DiffScannerClose",
    r#"
import java.util.NoSuchElementException;
import java.util.Scanner;

public class DiffScannerClose {
    public static void main(String[] args) {
        Scanner first = new Scanner(System.in);
        System.out.println("first=" + first.next());
        first.close();

        // The closed Scanner itself refuses every method but `close`.
        try {
            first.next();
            System.out.println("closed.next: no throw");
        } catch (IllegalStateException e) {
            System.out.println("closed.next: IllegalStateException " + e.getMessage());
        }
        try {
            first.hasNext();
            System.out.println("closed.hasNext: no throw");
        } catch (IllegalStateException e) {
            System.out.println("closed.hasNext: IllegalStateException " + e.getMessage());
        }
        first.close();
        System.out.println("double close: ok");

        // `close()` closed System.in itself, so a NEW Scanner sees end of
        // input — this is why a program that closes stdin and reads again
        // dies on a real JVM.
        Scanner second = new Scanner(System.in);
        System.out.println("new hasNext=" + second.hasNext());
        try {
            second.next();
            System.out.println("new.next: no throw");
        } catch (NoSuchElementException e) {
            System.out.println("new.next: NoSuchElementException");
        }
        try {
            second.nextLine();
            System.out.println("new.nextLine: no throw");
        } catch (NoSuchElementException e) {
            System.out.println("new.nextLine: NoSuchElementException " + e.getMessage());
        }
        try {
            second.nextInt();
            System.out.println("new.nextInt: no throw");
        } catch (NoSuchElementException e) {
            System.out.println("new.nextInt: NoSuchElementException");
        }
    }
}
"#,
    "alpha beta\ngamma\n"
);

differential_test!(
    diff_static_method_through_an_instance,
    "DiffStaticViaInstance",
    r#"
class StaticBase {
    static int calls = 0;
    static String who() { return "StaticBase"; }
    static int twice(int x) { return 2 * x; }
    static void hello() { System.out.println("hello"); }
    static long wide(long x) { return x + 1L; }
}

class StaticDerived extends StaticBase {}

public class DiffStaticViaInstance {
    static StaticBase make() {
        System.out.println("make() ran");
        return new StaticBase();
    }

    public static void main(String[] args) {
        StaticBase base = new StaticBase();

        // `obj.staticMethod(...)` — legal if discouraged.
        System.out.println(base.twice(4));
        base.hello();
        System.out.println(base.calls);
        System.out.println(base.wide(41L));

        // The receiver expression is evaluated for its side effects, then
        // discarded: `make() ran` prints before the result.
        System.out.println(make().twice(3));

        // Nothing is dereferenced, so a null receiver does not throw.
        StaticBase none = null;
        System.out.println(none.twice(7));

        // A static inherited from a superclass, reached both ways.
        StaticDerived derived = new StaticDerived();
        System.out.println(derived.who());
        System.out.println(StaticDerived.who());
    }
}
"#
);

