// Collection.removeIf(predicate) drops matching elements in place across every
// collection kind — HashSet/TreeSet rebuild their storage; LinkedList/
// ArrayDeque/Stack drop from the shared vector — and reports whether any went.
differential_test!(
    diff_remove_if,
    "DiffRemoveIf",
    r#"
import java.util.*;

public class DiffRemoveIf {
    public static void main(String[] args) {
        Set<Integer> hs = new HashSet<>(Arrays.asList(1, 2, 3, 4, 5, 6, 7, 8));
        boolean a = hs.removeIf(x -> x % 3 == 0);
        System.out.println(hs + " " + a);

        TreeSet<Integer> ts = new TreeSet<>(Arrays.asList(5, 3, 8, 1, 4, 9, 2, 7));
        ts.removeIf(x -> x > 4);
        System.out.println(ts);

        LinkedList<String> ll = new LinkedList<>(Arrays.asList("apple", "fig", "banana", "kiwi", "ox"));
        ll.removeIf(s -> s.length() > 3);
        System.out.println(ll);

        Deque<Integer> dq = new ArrayDeque<>(Arrays.asList(1, 2, 3, 4, 5, 6));
        dq.removeIf(x -> x % 2 == 1);
        System.out.println(dq);

        Stack<Integer> st = new Stack<>();
        for (int i = 1; i <= 8; i++) { st.push(i); }
        st.removeIf(x -> x > 5);
        System.out.println(st);

        // Return value: false when nothing matches, true when something goes.
        TreeSet<Integer> s2 = new TreeSet<>(Arrays.asList(10, 20, 30));
        System.out.println(s2.removeIf(x -> x > 100) + " " + s2);
        System.out.println(s2.removeIf(x -> x == 20) + " " + s2);
    }
}
"#
);

// The whole mutable Collection face — add/remove/clear/addAll/removeAll/
// retainAll/containsAll/stream — over EVERY backing it can hold (both element
// storage families), with bulk arguments crossing families (list.addAll(set)),
// a values() view writing entries through (add refuses with UOE), a TreeMap
// view clearing through, and an unmodifiable backing refusing everything.
differential_test!(
    diff_collection_face,
    "DiffCollectionFace",
    r#"
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.PriorityQueue;
import java.util.Stack;
import java.util.TreeMap;
import java.util.TreeSet;

public class DiffCollectionFace {
    static void exercise(String name, Collection<Integer> c) {
        System.out.println(name + " add " + c.add(42) + " " + c.add(7) + " -> " + c);
        System.out.println(name + " remove " + c.remove(42) + " " + c.remove(999) + " -> " + c);
        ArrayList<Integer> more = new ArrayList<>();
        more.add(1); more.add(2);
        System.out.println(name + " addAll " + c.addAll(more) + " -> " + c);
        System.out.println(name + " containsAll " + c.containsAll(more));
        System.out.println(name + " removeAll " + c.removeAll(more) + " -> " + c);
        ArrayList<Integer> keep = new ArrayList<>();
        keep.add(7);
        System.out.println(name + " retainAll " + c.retainAll(keep) + " -> " + c);
        System.out.println(name + " stream " + c.stream().map(x -> x * 2).count());
        c.clear();
        System.out.println(name + " clear -> " + c + " " + c.isEmpty());
    }

    public static void main(String[] args) {
        exercise("list", new ArrayList<Integer>());
        exercise("linked", new LinkedList<Integer>());
        exercise("hashset", new HashSet<Integer>());
        exercise("treeset", new TreeSet<Integer>());
        exercise("pq", new PriorityQueue<Integer>());
        exercise("stack", new Stack<Integer>());
        exercise("deque", new ArrayDeque<Integer>());

        // A list takes a SET argument for the bulk operations.
        ArrayList<Integer> li = new ArrayList<>();
        li.add(1); li.add(2); li.add(3);
        HashSet<Integer> hs = new HashSet<>();
        hs.add(2); hs.add(9);
        System.out.println("mixed addAll " + li.addAll(hs) + " -> " + li);
        System.out.println("mixed removeAll " + li.removeAll(hs) + " -> " + li);
        System.out.println("mixed containsAll " + li.containsAll(hs));

        // The values() view: add refuses, the rest write ENTRIES through.
        HashMap<String, Integer> m = new HashMap<>();
        m.put("a", 10); m.put("b", 25); m.put("c", 10); m.put("d", 30);
        Collection<Integer> vs = m.values();
        try { vs.add(5); System.out.println("view add no throw"); }
        catch (UnsupportedOperationException e) { System.out.println("view add UOE"); }
        System.out.println("view remove " + vs.remove(10) + " -> " + m);
        ArrayList<Integer> tens = new ArrayList<>();
        tens.add(10); tens.add(25);
        System.out.println("view removeAll " + vs.removeAll(tens) + " -> " + m);
        m.put("e", 40);
        ArrayList<Integer> forty = new ArrayList<>();
        forty.add(40);
        System.out.println("view retainAll " + vs.retainAll(forty) + " -> " + m);
        vs.clear();
        System.out.println("view clear -> " + m);

        // TreeMap views clear through too.
        TreeMap<String, Integer> tm = new TreeMap<>();
        tm.put("x", 1); tm.put("y", 2);
        tm.keySet().clear();
        System.out.println("treemap keyset clear -> " + tm);

        // Set faces over a TreeSet still do bulk operations.
        TreeSet<Integer> ts = new TreeSet<>();
        ts.add(5); ts.add(1); ts.add(9); ts.add(3);
        ArrayList<Integer> odds = new ArrayList<>();
        odds.add(1); odds.add(9);
        System.out.println("treeset removeAll " + ts.removeAll(odds) + " -> " + ts);
        TreeSet<Integer> ts2 = new TreeSet<>();
        ts2.add(5); ts2.add(1); ts2.add(9);
        System.out.println("treeset retainAll " + ts2.retainAll(odds) + " -> " + ts2);

        // Unmodifiable backing refuses every mutator through the face.
        ArrayList<Integer> base = new ArrayList<>();
        base.add(6);
        Collection<Integer> frozen = Collections.unmodifiableList(base);
        try { frozen.add(1); System.out.println("frozen add no throw"); }
        catch (UnsupportedOperationException e) { System.out.println("frozen add UOE"); }
        try { frozen.clear(); System.out.println("frozen clear no throw"); }
        catch (UnsupportedOperationException e) { System.out.println("frozen clear UOE " + base); }
    }
}
"#
);

// removeIf on the faces the plain diff_remove_if cannot reach: a
// PriorityQueue replays JDK 11's bulkRemove (test all in heap-array order,
// compact survivors STABLY, re-heapify — NOT the JDK 8 iterator-with-removeAt
// loop, which leaves a visibly different heap array); the Queue face works
// over both backings; a map's key/value views write ENTRIES through; a
// Collection can hold a widened List; and an unmodifiable list refuses.
differential_test!(
    diff_remove_if_queue_and_views,
    "DiffRemoveIfQV",
    r#"
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.PriorityQueue;
import java.util.Queue;
import java.util.Set;

public class DiffRemoveIfQV {
    public static void main(String[] args) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        int[] seed = {41, 17, 63, 5, 88, 29, 71, 12, 55, 34, 96, 8, 47, 23, 60};
        for (int s : seed) pq.offer(s);
        System.out.println(pq.removeIf(n -> n % 3 == 0) + " " + pq);
        System.out.println(pq.removeIf(n -> n > 1000) + " " + pq);
        // A removal pattern whose re-heapify visibly rearranges the array.
        PriorityQueue<Integer> pq2 = new PriorityQueue<>();
        int[] seed2 = {50, 90, 10, 95, 91, 30, 20, 96, 97, 92, 93, 35, 31, 25, 21};
        for (int s : seed2) pq2.offer(s);
        System.out.println(pq2.removeIf(n -> n >= 90) + " " + pq2);

        Queue<Integer> q1 = new LinkedList<>();
        q1.add(3); q1.add(14); q1.add(15); q1.add(9);
        System.out.println(q1.removeIf(n -> n > 10) + " " + q1);
        Queue<Integer> q2 = new PriorityQueue<>();
        q2.add(30); q2.add(1); q2.add(40); q2.add(11);
        System.out.println(q2.removeIf(n -> n > 10) + " " + q2);

        HashMap<String, Integer> m = new HashMap<>();
        m.put("apple", 1); m.put("fig", 2); m.put("banana", 3);
        Set<String> ks = m.keySet();
        System.out.println(ks.removeIf(k -> k.length() > 3) + " " + m);
        HashMap<String, Integer> m2 = new HashMap<>();
        m2.put("a", 10); m2.put("b", 25); m2.put("c", 10);
        Collection<Integer> vs = m2.values();
        System.out.println(vs.removeIf(v -> v == 10) + " " + m2);

        ArrayList<Integer> cl = new ArrayList<>();
        cl.add(2); cl.add(4); cl.add(7);
        Collection<Integer> c = cl;
        System.out.println(c.removeIf(n -> n % 2 == 0) + " " + c);

        ArrayList<Integer> base = new ArrayList<>();
        base.add(6);
        Collection<Integer> frozen = Collections.unmodifiableList(base);
        try { frozen.removeIf(n -> n > 0); System.out.println("no throw"); }
        catch (UnsupportedOperationException e) { System.out.println("UOE"); }
    }
}
"#
);

// java.util.ArrayDeque — a Deque and Queue (not a List): head-based
// push/pop/peekFirst, tail-based offer/peekLast, usable as a stack or FIFO;
// a copy constructor; and it forbids null elements.
differential_test!(
    diff_array_deque,
    "DiffArrayDeque",
    r#"
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Queue;

public class DiffArrayDeque {
    public static void main(String[] args) {
        Deque<Integer> d = new ArrayDeque<>();
        d.addFirst(1); d.addLast(2); d.push(0);          // push == addFirst (head)
        System.out.println(d + " " + d.peekFirst() + " " + d.peekLast());
        System.out.println(d.getFirst() + " " + d.getLast());
        System.out.println(d.pop() + " " + d.pollLast() + " " + d);

        // FIFO queue face.
        Queue<String> q = new ArrayDeque<>();
        q.offer("a"); q.offer("b"); q.offer("c");
        System.out.println(q.poll() + " " + q.peek() + " " + q);

        // LIFO stack face.
        ArrayDeque<Integer> st = new ArrayDeque<>();
        for (int i = 1; i <= 4; i++) { st.push(i); }
        System.out.println(st);                          // [4, 3, 2, 1]
        StringBuilder sb = new StringBuilder();
        while (!st.isEmpty()) { sb.append(st.pop()); }
        System.out.println(sb);                          // 4321

        // Copy constructor, for-each, contains/remove.
        ArrayDeque<Integer> c = new ArrayDeque<>(Arrays.asList(5, 6, 7, 6));
        int sum = 0;
        for (int x : c) { sum += x; }
        System.out.println(c + " " + sum + " " + c.contains(6));
        c.remove(6);                                     // removes the first 6
        System.out.println(c + " " + c.size());

        // Null is rejected on every insertion (a String deque, so the null
        // literal types cleanly).
        Deque<String> s = new ArrayDeque<>();
        s.add("keep");
        try {
            s.addFirst(null);
        } catch (NullPointerException e) {
            System.out.println("no nulls: " + s);
        }
    }
}
"#
);

// java.util.Stack — a Vector-backed LIFO. push/pop/peek act on the top (the
// end); it is a List, so every list method and for-each work; an empty
// pop/peek throws EmptyStackException.
differential_test!(
    diff_stack_lifo_and_list,
    "DiffStack",
    r#"
import java.util.List;
import java.util.Stack;

public class DiffStack {
    public static void main(String[] args) {
        Stack<Integer> s = new Stack<>();
        s.push(1); s.push(2); s.push(3);
        System.out.println(s);                          // [1, 2, 3]
        System.out.println(s.peek() + " " + s.pop() + " " + s);
        System.out.println(s.empty() + " " + s.size() + " " + s.isEmpty());
        s.push(5);
        System.out.println(s.search(1) + " " + s.search(5) + " " + s.search(99));
        System.out.println(s.get(0) + " " + s.contains(5) + " " + s.indexOf(2));

        // A Stack is a List and a Collection.
        List<String> ls = new Stack<>();
        ls.add("a"); ls.add("b"); ls.add(0, "z");
        System.out.println(ls);                         // [z, a, b]
        for (String x : ls) { System.out.print(x); }
        System.out.println();

        // Drain LIFO.
        Stack<String> st = new Stack<>();
        st.push("x"); st.push("y"); st.push("w");
        StringBuilder out = new StringBuilder();
        while (!st.empty()) { out.append(st.pop()); }
        System.out.println(out + " tail=" + s);

        // Empty-stack pop throws EmptyStackException, not NoSuchElementException.
        Stack<Integer> e = new Stack<>();
        try {
            e.pop();
        } catch (java.util.EmptyStackException ex) {
            System.out.println("empty: " + ex.getMessage());
        }
    }
}
"#
);

