// `entrySet()` assigns to its own declared type; the view's clear/remove
// write through to the map; add on the VIEW throws; a HashSet declared as
// `Set<Map.Entry<K, V>>` is a real, mutable set of standalone entries.
differential_test!(
    diff_entry_set_declared_type,
    "DiffEntrySetDecl",
    r#"
import java.util.AbstractMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
public class DiffEntrySetDecl {
    static int total(Set<Map.Entry<String, Integer>> entries) {
        int sum = 0;
        for (Map.Entry<String, Integer> e : entries) sum += e.getValue();
        return sum;
    }
    public static void main(String[] args) {
        Map<String, Integer> m = new HashMap<>();
        m.put("a", 1);
        m.put("b", 2);
        Set<Map.Entry<String, Integer>> es = m.entrySet();
        System.out.println(es.size() + " " + total(es));
        System.out.println(es.remove(new AbstractMap.SimpleEntry<>("a", 9)));
        System.out.println(es.remove(new AbstractMap.SimpleEntry<>("a", 1)));
        System.out.println(m);
        System.out.println(es.contains(new AbstractMap.SimpleEntry<>("b", 2)));
        try {
            es.add(new AbstractMap.SimpleEntry<>("c", 3));
        } catch (UnsupportedOperationException e) {
            System.out.println("UOE");
        }
        m.entrySet().clear();
        System.out.println(m.isEmpty() + " " + es.isEmpty());
        Map<String, Integer> t = new TreeMap<>();
        t.put("k", 1);
        t.entrySet().clear();
        System.out.println(t);
        Set<Map.Entry<String, Integer>> own = new HashSet<>();
        own.add(new AbstractMap.SimpleEntry<>("x", 5));
        System.out.println(own + " " + own.size());
    }
}
"#
);

// AbstractMap.SimpleEntry is a standalone Map.Entry: getKey/getValue/
// setValue/toString/equals all behave, including against a live map entry.
differential_test!(
    diff_simple_entry,
    "DiffSimpleEntry",
    r#"
import java.util.AbstractMap;
import java.util.HashMap;
import java.util.Map;
public class DiffSimpleEntry {
    public static void main(String[] args) {
        Map.Entry<String, Integer> e = new AbstractMap.SimpleEntry<>("x", 5);
        System.out.println(e.getKey() + " " + e.getValue());
        e.setValue(9);
        System.out.println(e);
        System.out.println(e.getValue());
        Map<String, Integer> p = new HashMap<>();
        p.put("x", 9);
        for (Map.Entry<String, Integer> live : p.entrySet()) {
            System.out.println(live.equals(e) + " " + e.equals(live));
            System.out.println(live.hashCode() == e.hashCode());
        }
        System.out.println(e.equals("x"));
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-6 interface defaults: most-specific default resolution, lambdas
// inside default methods, JLS §9.8 Object-method exclusions, and ambiguous
// inherited constants.

// JLS §9.4.1: the MOST SPECIFIC default wins, regardless of where the
// interfaces sit in the implements list (caturra used to answer with
// whichever interface the traversal reached first).
differential_test!(
    diff_interface_default_most_specific,
    "DiffIfaceDefault",
    r#"
interface Top { default String greet() { return "top"; } }
interface Left extends Top { default String greet() { return "left"; } }
interface Right extends Top { }
interface Deep extends Left { default String greet() { return "deep"; } }
class ViaLeftRight implements Left, Right { }
class ViaRightLeft implements Right, Left { }
class ViaDeep implements Right, Deep { }
public class DiffIfaceDefault {
    public static void main(String[] a) {
        Top t = new ViaLeftRight();
        System.out.println(t.greet());
        System.out.println(new ViaRightLeft().greet());
        System.out.println(new ViaDeep().greet());
    }
}
"#
);

// A lambda body is lexically scoped (JLS §15.27.2): a bare `apply(y)` inside
// `y -> apply(y) * 2` means the ENCLOSING instance's method, never the SAM
// the lambda defines — the decorator idiom used to be infinite recursion.
differential_test!(
    diff_lambda_in_default_method,
    "DiffLambdaDefault",
    r"
interface Fn {
    int apply(int x);
    default int applyTwice(int x) { return apply(apply(x)); }
    default Fn doubled() { return y -> apply(y) * 2; }
    default Fn plus(int k) { return y -> apply(y) + k; }
    default Fn explicit() { return y -> this.apply(y) * 3; }
}
public class DiffLambdaDefault {
    int bump(int x) { return x + 10; }
    Fn wrap() { return y -> bump(y); }
    public static void main(String[] a) {
        Fn inc = x -> x + 1;
        System.out.println(inc.applyTwice(5));
        System.out.println(inc.doubled().apply(5));
        System.out.println(inc.plus(5).plus(100).apply(1));
        System.out.println(inc.explicit().apply(4));
        System.out.println(new DiffLambdaDefault().wrap().apply(1));
    }
}
"
);

