// ---------------------------------------------------------------------------
// Varargs (audit round 8): what a lone array argument means, forwarding one,
// and which of several variable-arity overloads wins.
// ---------------------------------------------------------------------------

// The most famous varargs gotcha: a lone REFERENCE array IS the varargs array,
// but a PRIMITIVE one is not — `T` cannot be `int`, so it infers as `int[]` and
// `Arrays.asList(int[])` is a ONE-element `List<int[]>`. Plus a null array
// (NullPointerException, not an aborted run) and `Collections.addAll` over the
// collections other than `List`.
differential_test!(
    diff_varargs_array_arguments,
    "DiffVarargsArrays",
    r#"
import java.util.*;

public class DiffVarargsArrays {
    public static void main(String[] args) {
        String[] refs = {"a", "b", "c"};
        System.out.println(Arrays.asList(refs) + " " + Arrays.asList(refs).size());

        int[] prims = {1, 2, 3};
        List<int[]> wrapped = Arrays.asList(prims);
        System.out.println(wrapped.size() + " " + (wrapped.get(0) == prims) + " " + wrapped.get(0)[2]);

        double[] ds = {1.5, 2.5};
        System.out.println(Arrays.asList(ds).size());

        Integer[] boxed = {1, 2, 3};
        System.out.println(Arrays.asList(boxed).size());

        String[] missing = null;
        try { Arrays.asList(missing); } catch (NullPointerException e) { System.out.println("NPE"); }

        Set<String> set = new HashSet<>();
        System.out.println(Collections.addAll(set, "a", "b", "a") + " " + set.size());
        TreeSet<Integer> sorted = new TreeSet<>();
        System.out.println(Collections.addAll(sorted, 3, 1, 2) + " " + sorted);
        Deque<String> deque = new ArrayDeque<>();
        Collections.addAll(deque, "p", "q");
        System.out.println(deque + " " + Collections.addAll(set));
    }
}
"#
);

// Forwarding a varargs parameter: `printf(fmt, parts)` inside a
// `void log(String fmt, Object... parts)` passes the ARRAY, whose elements are
// the format arguments. And a method reference to a varargs method fits a
// functional interface of ANY arity, not only the declared one.
differential_test!(
    diff_varargs_forwarding,
    "DiffVarargsForward",
    r#"
import java.util.*;

interface Take3 { String of(String a, String b, String c); }
interface Take0 { String of(); }

public class DiffVarargsForward {
    static void log(String fmt, Object... parts) { System.out.printf(fmt, parts); }
    static String render(String fmt, Object... parts) { return String.format(fmt, parts); }
    static String pack(String... parts) { return parts.length + Arrays.toString(parts); }

    public static void main(String[] args) {
        log("%s=%d%n", "n", 3);
        log("none%n");
        System.out.print(render("%s/%s%n", "a", "b"));
        Object[] direct = {"z", 9};
        System.out.printf("%s-%d%n", direct);
        System.out.printf("%b%n", (Object[]) null);

        Take3 three = DiffVarargsForward::pack;
        System.out.println(three.of("a", "b", "c"));
        Take0 none = DiffVarargsForward::pack;
        System.out.println(none.of());
    }
}
"#
);

// Which variable-arity overload wins (JLS §15.12.2.5). Specificity compares
// each method's declared parameter inside its fixed prefix and its varargs
// ELEMENT beyond it, so overloads of DIFFERENT arity are comparable and
// `s(String, Object...)` beats `s(Object...)`.
differential_test!(
    diff_varargs_specificity_across_arities,
    "DiffVarargsSpecific",
    r#"
public class DiffVarargsSpecific {
    static String f(Integer... a) { return "I" + a.length; }
    static String f(Object... a) { return "O" + a.length; }
    static String g(String x, Object... a) { return "G" + a.length; }
    static String g(Object... a) { return "H" + a.length; }
    static String h(String x, String y, Object... a) { return "2" + a.length; }
    static String h(String x, Object... a) { return "1" + a.length; }

    public static void main(String[] args) {
        System.out.println(f(1, 2));
        System.out.println(g("a", "b"));
        System.out.println(g(1, 2));
        System.out.println(h("a", "b", "c"));
        System.out.println(h("a", 1));
    }
}
"#
);

// Specificity is SUBTYPING, not method-invocation conversion: `int` is not a
// subtype of `Object`, so neither variable-arity method is more specific and
// javac calls the call ambiguous. caturra silently preferred the primitive one.
differential_reject!(
    reject_ambiguous_primitive_and_reference_varargs,
    "RejVarargsAmbiguous",
    r#"
public class RejVarargsAmbiguous {
    static String b(int... x) { return "iv" + x.length; }
    static String b(Object... x) { return "ov" + x.length; }
    public static void main(String[] args) {
        System.out.println(b(1, 2));
    }
}
"#
);

// ---------------------------------------------------------------------------
// Streams (audit round 8): a pipeline is a TYPE and a value, not only a chained
// expression — sources, operations, collectors, and the rules a stream obeys.
// ---------------------------------------------------------------------------

// `Stream<T>` and `IntStream` name types, so a pipeline can be held in a
// variable; and a stream can start somewhere other than a collection —
// `Stream.of`, `Stream.empty`, `Stream.concat`, `IntStream.of`,
// `Arrays.stream` (over a reference array and over a primitive one), and
// `entrySet().stream()`, whose elements are whole `Map.Entry`s.
differential_test!(
    diff_stream_types_and_sources,
    "DiffStreamSources",
    r#"
import java.util.*;
import java.util.stream.*;

public class DiffStreamSources {
    public static void main(String[] args) {
        List<Integer> ns = new ArrayList<>(Arrays.asList(1, 2, 3));
        Stream<Integer> held = ns.stream();
        System.out.println(held.count());
        var inferred = ns.stream();
        System.out.println(inferred.count());
        IntStream ints = IntStream.range(0, 4);
        System.out.println(ints.sum());

        System.out.println(Stream.of("a", "b", "c").collect(Collectors.toList()));
        System.out.println(Stream.empty().count());
        System.out.println(Stream.concat(Stream.of("a"), Stream.of("b")).collect(Collectors.toList()));
        System.out.println(IntStream.of(1, 2, 3).sum());

        String[] words = {"x", "y", "z"};
        System.out.println(Arrays.stream(words).collect(Collectors.toList()));
        int[] values = {4, 5, 6};
        System.out.println(Arrays.stream(values).sum());

        Map<String, Integer> m = new TreeMap<>();
        m.put("one", 1);
        m.put("two", 2);
        System.out.println(m.entrySet().stream()
            .map(e -> e.getKey() + "=" + e.getValue())
            .collect(Collectors.toList()));
    }
}
"#
);

// The operations that used to be refused with a FALSE reason about
// functional-interface types: `flatMap`, all of `reduce`, `toArray`,
// `mapToDouble`/`mapToLong` (whose `sum()` has its own numeric width), and
// `summaryStatistics()`. Plus a key extractor typed from the stream's element,
// and a `char`/`boolean` result that must stay its own wrapper — a bare int
// cannot say which of the three it is, and `map(s -> s.charAt(0))` was a
// stream of 97s.
differential_test!(
    diff_stream_operations,
    "DiffStreamOps",
    r#"
import java.util.*;
import java.util.stream.*;

public class DiffStreamOps {
    public static void main(String[] args) {
        List<List<String>> nested = new ArrayList<>();
        nested.add(new ArrayList<>(Arrays.asList("a", "b")));
        nested.add(new ArrayList<>(Arrays.asList("c")));
        System.out.println(nested.stream().flatMap(l -> l.stream()).collect(Collectors.toList()));

        List<Integer> ns = new ArrayList<>(Arrays.asList(1, 2, 3, 4));
        System.out.println(ns.stream().reduce(0, (a, b) -> a + b));
        System.out.println(ns.stream().reduce((a, b) -> a + b).get());
        System.out.println(new ArrayList<Integer>().stream().reduce((a, b) -> a + b).isPresent());
        System.out.println(Arrays.toString(ns.stream().toArray()));
        System.out.println(ns.stream().mapToDouble(x -> x).sum());
        System.out.println(ns.stream().mapToLong(x -> x).sum());
        System.out.println(Arrays.toString(ns.stream().mapToInt(x -> x).toArray()));
        System.out.println(ns.stream().mapToInt(x -> x).boxed().collect(Collectors.toList()));

        IntSummaryStatistics stats = IntStream.of(3, 1, 4, 1, 5).summaryStatistics();
        System.out.println(stats.getCount() + " " + stats.getSum() + " " + stats.getMin()
            + " " + stats.getMax() + " " + stats.getAverage());
        System.out.println(stats);

        List<String> ws = new ArrayList<>(Arrays.asList("bb", "a", "ccc", "dd"));
        System.out.println(ws.stream().sorted(Comparator.comparing(s -> s.length()))
            .collect(Collectors.toList()));
        System.out.println(ws.stream().map(s -> s.charAt(0)).collect(Collectors.toList()));
        System.out.println(ws.stream().map(s -> s.isEmpty()).collect(Collectors.toList()));
    }
}
"#
);

// The collectors beyond `toList`/`toSet`/`joining`: `counting`, `groupingBy`
// (with and without a downstream), `partitioningBy` (whose map always holds
// both keys), `toMap` (with a merge function), and the summing/averaging
// family. Each takes a lambda whose parameter is the STREAM's element — a
// target type that comes from two levels up.
differential_test!(
    diff_stream_collectors,
    "DiffStreamCollectors",
    r#"
import java.util.*;
import java.util.stream.*;

public class DiffStreamCollectors {
    public static void main(String[] args) {
        List<String> ws = new ArrayList<>(Arrays.asList("apple", "avocado", "banana", "blue"));
        System.out.println(ws.stream().collect(Collectors.counting()));
        Map<Character, List<String>> byLetter = ws.stream()
            .collect(Collectors.groupingBy(w -> w.charAt(0)));
        System.out.println(byLetter);
        Map<Character, Long> counts = ws.stream()
            .collect(Collectors.groupingBy(w -> w.charAt(0), Collectors.counting()));
        System.out.println(counts);
        System.out.println(ws.stream()
            .collect(Collectors.partitioningBy(w -> w.length() > 4)));
        Map<String, Integer> lengths = ws.stream()
            .collect(Collectors.toMap(w -> w, w -> w.length()));
        System.out.println(lengths);
        Map<Character, String> firsts = ws.stream()
            .collect(Collectors.toMap(w -> w.charAt(0), w -> w, (a, b) -> a));
        System.out.println(firsts);
        System.out.println(ws.stream().collect(Collectors.summingInt(w -> w.length())));
        System.out.println(ws.stream().collect(Collectors.averagingInt(w -> w.length())));
        System.out.println(new ArrayList<String>().stream()
            .collect(Collectors.averagingInt(w -> w.length())));
    }
}
"#
);

// The rules a stream obeys: `limit`/`skip` reject a negative count outright, a
// pipeline is SINGLE-USE, and a terminal fails fast when the collection it was
// opened over is modified while it runs — after the traversal, exactly where
// `ArrayList`'s spliterator checks its modCount, so every original element is
// still seen.
differential_test!(
    diff_stream_rules,
    "DiffStreamRules",
    r#"
import java.util.*;
import java.util.stream.*;

public class DiffStreamRules {
    public static void main(String[] args) {
        List<String> ws = new ArrayList<>(Arrays.asList("a", "b", "c"));
        try { ws.stream().limit(-1).count(); }
        catch (IllegalArgumentException e) { System.out.println("limit " + e.getMessage()); }
        try { ws.stream().skip(-2).count(); }
        catch (IllegalArgumentException e) { System.out.println("skip " + e.getMessage()); }
        System.out.println(ws.stream().limit(2).collect(Collectors.toList()));
        System.out.println(ws.stream().skip(2).collect(Collectors.toList()));

        Stream<String> once = ws.stream();
        System.out.println(once.count());
        try { once.count(); }
        catch (IllegalStateException e) { System.out.println("ISE " + e.getMessage()); }

        List<String> seen = new ArrayList<>();
        try {
            ws.stream().forEach(s -> { if (s.equals("a")) { ws.add("d"); } seen.add(s); });
            System.out.println("no CME");
        } catch (ConcurrentModificationException e) {
            System.out.println("CME");
        }
        System.out.println(seen);
    }
}
"#
);

// ---------------------------------------------------------------------------
// The Object contract (audit round 8): what every reference inherits, and the
// rules `Object`'s own methods impose on a class that touches them.
// ---------------------------------------------------------------------------

// `getClass()` belongs to every reference — a `String`, a collection, a boxed
// wrapper — and the `Class` it answers is INTERNED, so `getSuperclass()` is
// `Object.class` itself and `Class.toString()` reads `class java.lang.Object`.
differential_test!(
    diff_object_class_handles,
    "DiffObjectClass",
    r#"
import java.util.*;

class Plain {}

public class DiffObjectClass {
    public static void main(String[] args) {
        System.out.println("hi".getClass().getName());
        System.out.println(new ArrayList<String>().getClass().getName());
        System.out.println(new StringBuilder().getClass().getName());
        Integer boxed = 5;
        System.out.println(boxed.getClass() == Integer.class);
        System.out.println(boxed.getClass().getName());

        Class<?> c = new Plain().getClass();
        System.out.println(c.getSuperclass().getName());
        System.out.println(c.getSuperclass() == Object.class);
        System.out.println(c.getSuperclass().equals(Object.class));
        System.out.println(Object.class.toString());
        System.out.println(String.class);
        System.out.println(c.getSuperclass().getSuperclass());
    }
}
"#
);

// `Object`'s defaults, reached from a class that overrides one of them:
// `toString()` is `getName() + "@" + Integer.toHexString(hashCode())` with the
// object's OWN hash, and `super.hashCode()`/`super.toString()`/`super.equals()`
// reach Object's — which used to abort the run outright.
differential_test!(
    diff_object_defaults,
    "DiffObjectDefaults",
    r#"
class FixedHash {
    @Override public int hashCode() { return 255; }
}

class ViaSuper {
    @Override public int hashCode() { return super.hashCode(); }
    @Override public boolean equals(Object o) { return super.equals(o); }
    String parentToString() { return super.toString(); }
}

public class DiffObjectDefaults {
    public static void main(String[] args) {
        FixedHash f = new FixedHash();
        System.out.println(f.hashCode());
        System.out.println(f.toString().equals("FixedHash@ff"));
        System.out.println(f.toString().equals(
            f.getClass().getName() + "@" + Integer.toHexString(f.hashCode())));

        ViaSuper v = new ViaSuper();
        System.out.println(v.hashCode() == v.hashCode());
        System.out.println(v.equals(v));
        System.out.println(v.equals(new ViaSuper()));
        System.out.println(v.parentToString().equals(v.toString()));
    }
}
"#
);

// `Cloneable` is a marker interface, and `Object.clone()` consults it: a class
// that implements it gets a field-by-field copy, and one that does not gets a
// `CloneNotSupportedException` named after itself.
differential_test!(
    diff_object_clone,
    "DiffObjectClone",
    r#"
class Copyable implements Cloneable {
    int x = 5;
    String name = "c";
    Object copy() throws CloneNotSupportedException { return this.clone(); }
}

class NotCopyable {
    int x = 7;
    Object copy() throws CloneNotSupportedException { return this.clone(); }
}

public class DiffObjectClone {
    public static void main(String[] args) throws Exception {
        Copyable original = new Copyable();
        Copyable copy = (Copyable) original.copy();
        System.out.println(copy.x + " " + copy.name + " " + (copy == original));
        copy.x = 9;
        System.out.println(original.x + " " + copy.x);

        try {
            new NotCopyable().copy();
            System.out.println("cloned");
        } catch (CloneNotSupportedException e) {
            System.out.println(e.getMessage() + " / " + e.getClass().getName());
        }
    }
}
"#
);

// `Object`'s four FINAL methods may not be declared by any class (JLS §8.4.3.3).
differential_reject!(
    reject_overriding_final_object_method,
    "RejFinalObjectMethod",
    r"
public class RejFinalObjectMethod {
    static class Bad {
        public final Class<?> getClass() { return null; }
    }
    public static void main(String[] args) {
        System.out.println(new Bad().getClass());
    }
}
"
);

// `@Override equals(SubType)` overrides nothing — the classic bug the
// annotation exists to catch, which caturra's erasure-tolerant matcher let
// through because `Object.equals`'s parameter really is `Object`.
differential_reject!(
    reject_override_annotation_on_equals_overload,
    "RejEqualsOverload",
    r"
public class RejEqualsOverload {
    static class Bad {
        @Override public boolean equals(Bad o) { return true; }
    }
    public static void main(String[] args) {
        System.out.println(new Bad().equals(new Bad()));
    }
}
"
);

// JLS §15.20.2: `instanceof` between two unrelated FINAL types can never be
// true, so it is a compile error rather than an answer of `false`.
differential_reject!(
    reject_impossible_instanceof,
    "RejImpossibleInstanceof",
    r#"
public class RejImpossibleInstanceof {
    public static void main(String[] args) {
        String s = "x";
        System.out.println(s instanceof Integer);
    }
}
"#
);

// ---------------------------------------------------------------------------
// Local and anonymous class scoping (audit round 8): what a nested class can
// see, and what it may not.
// ---------------------------------------------------------------------------

// `Outer.this` (JLS §15.8.4) reaches the enclosing instance from an anonymous
// OR a local class, including through a shadowing field of the same name. The
// capture pass did not recognize a qualified `this` as needing the outer link,
// so every one of these was "non-static variable this cannot be referenced
// from a static context".
differential_test!(
    diff_qualified_this_in_nested_classes,
    "DiffQualifiedThis",
    r#"
interface Job { String run(); }

public class DiffQualifiedThis {
    private String tag = "outer";
    int x = 1;

    Job anonymous() {
        return new Job() {
            int x = 5;
            public String run() {
                return DiffQualifiedThis.this.tag + " " + x + " " + DiffQualifiedThis.this.x;
            }
        };
    }

    String local() {
        class L {
            String tag = "inner";
            String read() { return tag + "/" + DiffQualifiedThis.this.tag; }
        }
        return new L().read();
    }

    String viaMethod() {
        return new Job() {
            public String run() { return DiffQualifiedThis.this.hi(); }
        }.run();
    }

    String hi() { return tag + "!"; }

    public static void main(String[] args) {
        DiffQualifiedThis o = new DiffQualifiedThis();
        System.out.println(o.anonymous().run());
        System.out.println(o.local());
        System.out.println(o.viaMethod());
    }
}
"#
);

// A local class keeps its own constructors: the captured values are threaded
// through a `this(...)` delegation (which used to match the constructor's own
// new signature and recurse until the stack blew), an anonymous class can
// extend a local one, and a local class in a nested block can extend a local
// class from the enclosing block. `getSimpleName()` is the name the source
// wrote, not caturra's hoisted `Name$LocalN`.
differential_test!(
    diff_local_class_shapes,
    "DiffLocalClasses",
    r#"
public class DiffLocalClasses {
    public static void main(String[] args) {
        int n = 3;
        class C {
            int m;
            C() { this(6); }
            C(int m) { this.m = m; }
            int v() { return m + n; }
        }
        System.out.println(new C().v());
        System.out.println(new C(1).v());

        class Base { String tag() { return "base"; } }
        Base b = new Base() { String tag() { return "anon-of-local:" + super.tag(); } };
        System.out.println(b.tag());

        {
            class D extends Base { String tag() { return super.tag() + "+d"; } }
            System.out.println(new D().tag());
            System.out.println(new D().getClass().getSimpleName());
        }

        class WithConstant { static final int F = 3; }
        System.out.println(WithConstant.F);
    }
}
"#
);

// A field initializer and an instance initializer block are NOT in the
// constructor's scope, even though they run inside it (JLS §8.3.1): the
// parameters are invisible, so the initializer reads the FIELD's default.
differential_test!(
    diff_initializer_scope,
    "DiffInitScope",
    r#"
import java.util.*;

class Holder {
    private List<String> items = new ArrayList<>();
    int size;
    int copy;
    { size = items.size(); copy = size + 1; System.out.println("block: size=" + size + " copy=" + copy); }

    Holder(List<String> items) {
        System.out.println("ctor: param=" + items.size() + " field=" + this.items.size());
    }
    Holder() { System.out.println("noarg: field=" + items.size()); }
}

public class DiffInitScope {
    public static void main(String[] args) {
        List<String> given = new ArrayList<>();
        given.add("a");
        new Holder(given);
        new Holder();
    }
}
"#
);

