// ---------------------------------------------------------------------------
// Round-9 cluster: inner-class instantiation (JLS §8.1.3, §15.9).
// ---------------------------------------------------------------------------

// `p.new Inner()` evaluates and NULL-CHECKS the qualifier before the arguments.
// caturra passed it straight through as the leading constructor argument, so a
// null enclosing instance built the object anyway and the argument's side
// effects had already run.
differential_test!(
    diff_qualified_new_null_check,
    "DiffQualifiedNew",
    r#"
public class DiffQualifiedNew {
    int t = 1;
    class Inner {
        Inner(int x) { System.out.println("Inner " + x + " t=" + t); }
    }
    static int side() { System.out.println("side effect"); return 9; }
    public static void main(String[] args) {
        DiffQualifiedNew o = new DiffQualifiedNew();
        o.new Inner(1);
        try {
            DiffQualifiedNew n = null;
            n.new Inner(side());
            System.out.println("no throw");
        } catch (NullPointerException e) {
            System.out.println("NPE");
        }
        System.out.println("done");
    }
}
"#
);

// The inner-class construction shapes: a qualified nested type NAME (as a
// return type, a parameter, a type argument, an array), a constructor that
// delegates with `this(...)`, an inner class extending another inner class, an
// INHERITED inner class, one built from inside an anonymous class, and one built
// inside a lambda (whose qualifier the capture pass never even looked at).
differential_test!(
    diff_inner_class_shapes,
    "DiffInnerShapes",
    r#"
import java.util.*;
import java.util.function.Supplier;
class Host {
    static class Point { public String toString() { return "P"; } }
    class Bound { public String toString() { return "B"; } }
}
class BaseHost {
    int b = 5;
    class Inherited { int g() { return b; } }
}
public class DiffInnerShapes extends BaseHost {
    int tag = 9;
    class A { public String toString() { return "A" + tag; } }
    class Chained {
        int k;
        Chained() { this(99); }
        Chained(int k) { this.k = k; }
        public String toString() { return "C(" + tag + "," + k + ")"; }
    }
    class Sub extends A { }
    Supplier<Object> field = () -> "from field " + tag;
    static Host.Point make() { return new Host.Point(); }
    static void take(Host.Point p) { System.out.println("took " + p); }
    void useInherited() { System.out.println(new Inherited().g()); }
    public static void main(String[] args) {
        System.out.println(make());
        take(new Host.Point());
        List<Host.Point> l = new ArrayList<Host.Point>();
        l.add(new Host.Point());
        System.out.println(l);
        Host h = new Host();
        List<Host.Bound> m = new ArrayList<>();
        m.add(h.new Bound());
        System.out.println(m);
        Host.Point[] arr = new Host.Point[2];
        arr[0] = new Host.Point();
        System.out.println(arr[0] + " " + arr[1] + " " + arr.length);
        DiffInnerShapes o = new DiffInnerShapes();
        System.out.println(o.new Chained());
        System.out.println(o.new Sub());
        o.useInherited();
        System.out.println(o.field.get());
        Supplier<Object> s = () -> o.new A();
        System.out.println(s.get());
    }
}
"#
);

// An anonymous class in a FIELD INITIALIZER that captures the enclosing
// instance. The capture pass found the captures but never passed them at the
// `new` site — field initializers were visited in one phase and not the other.
differential_test!(
    diff_anonymous_class_in_field_initializer,
    "DiffAnonField",
    r#"
public class DiffAnonField {
    interface Act { void run(); }
    int tag = 3;
    class A { public String toString() { return "A" + tag; } }
    Act plain = new Act() { public void run() { System.out.println("plain " + tag); } };
    Act inner = new Act() {
        public void run() {
            System.out.println(new A());
            System.out.println(DiffAnonField.this.new A());
        }
    };
    public static void main(String[] args) {
        DiffAnonField o = new DiffAnonField();
        o.plain.run();
        o.inner.run();
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-9 cluster: the Collections utilities.
// ---------------------------------------------------------------------------

// `Collections` declares max/min/frequency/disjoint/addAll over COLLECTION and
// the rest over LIST — caturra demanded a statically-`List` argument for all of
// them, so a Set was refused outright and a `LinkedList`-typed variable was too.
// Plus the methods that were missing entirely, and `nCopies(n, null)`.
differential_test!(
    diff_collections_over_any_collection,
    "DiffCollectionsAny",
    r#"
import java.util.*;
public class DiffCollectionsAny {
    public static void main(String[] args) {
        Set<Integer> s = new HashSet<>(Arrays.asList(4, 9, 2));
        System.out.println("max=" + Collections.max(s) + " min=" + Collections.min(s));
        System.out.println("freq=" + Collections.frequency(s, Integer.valueOf(9)));
        System.out.println("disj=" + Collections.disjoint(s, new HashSet<>(Arrays.asList(1))));
        System.out.println("addAll=" + Collections.addAll(s, 5));
        System.out.println("s=" + new TreeSet<>(s));
        LinkedList<Integer> a = new LinkedList<>(Arrays.asList(1, 2, 3, 4, 5));
        Collections.rotate(a, 2);
        System.out.println("rot=" + a);
        Collections.reverse(a);
        System.out.println("rev=" + a);
        List<String> r = new ArrayList<>(Arrays.asList("a", "b", "a", "c"));
        System.out.println("replaced=" + Collections.replaceAll(r, "a", "Z") + " " + r);
        List<Integer> l = Arrays.asList(1, 2, 3, 4, 5, 3, 4);
        System.out.println("iosl=" + Collections.indexOfSubList(l, Arrays.asList(3, 4)));
        System.out.println("liosl=" + Collections.lastIndexOfSubList(l, Arrays.asList(3, 4)));
        System.out.println("miss=" + Collections.indexOfSubList(l, Arrays.asList(9)));
        System.out.println("empty=" + Collections.indexOfSubList(l, new ArrayList<Integer>()));
        List<String> nulls = Collections.nCopies(3, null);
        System.out.println("nulls=" + nulls);
    }
}
"#
);

// The immutable views: copy-constructing from one, printing one in a
// concatenation, and the out-of-range message each JDK view words its own way
// (`nCopies` and `singletonList` are AbstractLists; the shared empty list
// reports the index alone; `Arrays.asList` indexes its array, so the exception
// CLASS differs).
differential_test!(
    diff_collection_view_messages,
    "DiffViewMessages",
    r#"
import java.util.*;
public class DiffViewMessages {
    public static void main(String[] args) {
        System.out.println("el=" + Collections.emptyList());
        System.out.println("em=" + Collections.emptyMap());
        System.out.println("es=" + Collections.emptySet());
        System.out.println(new HashSet<>(Collections.singleton("z")));
        System.out.println(new ArrayList<>(Collections.emptyList()));
        System.out.println(new ArrayList<>(Collections.nCopies(2, "q")));
        System.out.println(new ArrayList<>(Collections.unmodifiableList(
            new ArrayList<>(Arrays.asList("u")))));
        List<String> arr = new ArrayList<>(Arrays.asList("x", "y"));
        try { arr.get(5); } catch (Exception e) { System.out.println("arraylist -> " + e.getMessage()); }
        try { Collections.unmodifiableList(arr).get(5); }
        catch (Exception e) { System.out.println("unmod -> " + e.getMessage()); }
        try { Collections.nCopies(2, "hi").get(2); }
        catch (Exception e) { System.out.println("ncopies -> " + e.getMessage()); }
        try { Collections.<String>emptyList().get(0); }
        catch (Exception e) { System.out.println("empty -> " + e.getMessage()); }
        try { Collections.singletonList("z").get(1); }
        catch (Exception e) { System.out.println("singleton -> " + e.getMessage()); }
        try { Arrays.asList("p", "q").get(4); }
        catch (Exception e) { System.out.println("aslist -> " + e.getClass().getName()); }
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-9 cluster: sorting contracts.
// ---------------------------------------------------------------------------

// `Arrays.rangeCheck`, in the JDK's order: a reversed range is an
// IllegalArgumentException naming both bounds, and an out-of-range one throws
// BEFORE anything is sorted (caturra sorted first and then complained, so the
// array was left half-sorted). The message is
// `new ArrayIndexOutOfBoundsException(index)`'s, which names the index alone.
differential_test!(
    diff_array_sort_range_checks,
    "DiffSortRange",
    r#"
import java.util.*;
public class DiffSortRange {
    public static void main(String[] args) {
        int[] a = {5, 4, 3, 2, 1};
        try { Arrays.sort(a, 3, 1); System.out.println("no throw"); }
        catch (Exception e) { System.out.println("E: " + e.getClass().getName() + " / " + e.getMessage()); }
        System.out.println("after reversed range: " + Arrays.toString(a));
        try { Arrays.sort(a, 1, 9); }
        catch (Exception e) { System.out.println("E: " + e.getClass().getName() + " / " + e.getMessage()); }
        System.out.println("after past-end: " + Arrays.toString(a));
        try { Arrays.binarySearch(a, 0, 9, 2); }
        catch (Exception e) { System.out.println("bs: " + e.getClass().getName() + " / " + e.getMessage()); }
        try { throw new ArrayIndexOutOfBoundsException(9); }
        catch (ArrayIndexOutOfBoundsException e) { System.out.println("ctor: " + e.getMessage()); }
        String[] s = {"e", "d", "c", "b", "a"};
        Arrays.sort(s, 1, 4);
        System.out.println("obj range: " + Arrays.toString(s));
        Integer[] b = {9, 8, 7, 6, 5};
        Arrays.sort(b, 1, 4, Comparator.<Integer>naturalOrder());
        System.out.println("obj range cmp: " + Arrays.toString(b));
        char[] c = {'z', 'y', 'x', 'w'};
        Arrays.sort(c, 1, 3);
        System.out.println("char range: " + new String(c));
        double[] d = {4.0, 3.0, 2.0, 1.0};
        Arrays.sort(d, 0, 2);
        System.out.println("double range: " + Arrays.toString(d));
        Object[] o = { "pear", "apple", "fig" };
        Arrays.sort(o);
        System.out.println("object sort: " + Arrays.toString(o));
    }
}
"#
);

// `binarySearch` promises no particular one of several EQUAL elements, but the
// index it returns is observable — and a half-open loop finds a different one
// from the JDK's closed `(low + high) >>> 1`.
differential_test!(
    diff_binary_search_duplicates,
    "DiffBinarySearchDups",
    r#"
import java.util.*;
public class DiffBinarySearchDups {
    public static void main(String[] args) {
        List<Integer> a = Arrays.asList(1,2,2,2,2,2,2,3,4,5,6,7,8,9,9,9,9,10);
        System.out.println("list 2 = " + Collections.binarySearch(a, 2));
        System.out.println("list 9 = " + Collections.binarySearch(a, 9));
        System.out.println("list absent = " + Collections.binarySearch(a, 100));
        int[] arr = {1,2,2,2,2,2,2,3,4,5,6,7,8,9,9,9,9,10};
        System.out.println("array 2 = " + Arrays.binarySearch(arr, 2));
        System.out.println("array 9 = " + Arrays.binarySearch(arr, 9));
        System.out.println("array absent = " + Arrays.binarySearch(arr, 0));
    }
}
"#
);

// The rest of the sorting contracts: an immutable list of 0 or 1 elements CAN
// be sorted (those classes override `sort` to do nothing), a comparator that
// modifies the list being sorted is a ConcurrentModificationException, a USER
// comparator inherits the interface's default combinators, and a method
// reference stands wherever a `Comparator` is expected.
differential_test!(
    diff_sorting_contracts,
    "DiffSortContracts",
    r#"
import java.util.*;
public class DiffSortContracts {
    static class ByValue implements Comparator<Integer> {
        public int compare(Integer a, Integer b) { return Integer.compare(a, b); }
    }
    static class P {
        String n; int a;
        P(String n, int a) { this.n = n; this.a = a; }
        public String toString() { return n + ":" + a; }
    }
    static int byDescending(Integer a, Integer b) { return Integer.compare(b, a); }
    public static void main(String[] args) {
        List<Integer> el = Collections.emptyList();
        el.sort(null);
        System.out.println("empty ok " + el);
        List<Integer> s1 = Collections.singletonList(5);
        s1.sort(null);
        System.out.println("single ok " + s1);
        List<Integer> m = new ArrayList<>(Arrays.asList(4, 2, 6, 1, 8));
        try {
            m.sort((a, b) -> { m.add(99); return Integer.compare(a, b); });
            System.out.println("no throw: " + m);
        } catch (ConcurrentModificationException e) {
            System.out.println("CME");
        }
        List<Integer> l = new ArrayList<>(Arrays.asList(3, 1, 2));
        Comparator<Integer> named = new ByValue();
        l.sort(named.reversed());
        System.out.println("named reversed: " + l);
        Comparator<Integer> anon = new Comparator<Integer>() {
            public int compare(Integer a, Integer b) { return Integer.compare(a, b); }
        };
        l.sort(anon.reversed());
        System.out.println("anon reversed: " + l);
        System.out.println("instanceof: " + (named instanceof Comparator));
        Comparator<Integer> ref = DiffSortContracts::byDescending;
        l.sort(ref);
        System.out.println("via variable: " + l);
        l.sort(DiffSortContracts::byDescending);
        System.out.println("inline: " + l);
        List<P> ps = new ArrayList<>(Arrays.asList(new P("bob", 30), new P("amy", 30), new P("cal", 25)));
        ps.sort(Comparator.comparingInt((P p) -> p.a)
                          .thenComparing(p -> p.n, Comparator.<String>reverseOrder()));
        System.out.println(ps);
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-9 cluster: the equals/hashCode contract.
// ---------------------------------------------------------------------------

// The LOOKUP methods take `Object` in Java, not the collection's own element
// type: `map.get(somethingElse)` compiles and answers null. Every reference has
// the Object methods, including a Queue- or Deque-typed one. A String and the
// wrappers are `Comparable`, so they assign to one.
differential_test!(
    diff_lookup_takes_object,
    "DiffLookupObject",
    r#"
import java.util.*;
public class DiffLookupObject {
    public static void main(String[] args) {
        Map<String, Integer> m = new HashMap<>();
        m.put("1", 1);
        System.out.println(m.get(Integer.valueOf(1)));
        System.out.println(m.containsKey(Integer.valueOf(1)));
        System.out.println(m.remove(Integer.valueOf(1)));
        System.out.println(m.getOrDefault(Integer.valueOf(1), -1));
        List<String> l = new ArrayList<>(Arrays.asList("a"));
        System.out.println(l.contains(Integer.valueOf(1)) + " " + l.indexOf(Integer.valueOf(1)));
        Queue<String> q = new LinkedList<>(Arrays.asList("a"));
        System.out.println("q.equals(q) = " + q.equals(q));
        System.out.println("q.hashCode == q.hashCode : " + (q.hashCode() == q.hashCode()));
        LinkedList<String> ll = new LinkedList<>(Arrays.asList("a", "b", "a"));
        System.out.println(ll.removeFirstOccurrence("a") + " " + ll.removeLastOccurrence("a") + " " + ll);
        Comparable<String> cs = "abc";
        System.out.println(cs.equals("abc") + " " + cs.compareTo("abd"));
        Comparable<Integer> ci = 5;
        System.out.println(ci.equals(5));
        System.out.println(Objects.hash((Object[]) null));
        Object[] n = null;
        System.out.println(Objects.hash(n) + " " + Arrays.hashCode((Object[]) null));
    }
}
"#
);

// `AbstractSet.equals` is `size == size && containsAll(other)` — and
// `containsAll` asks THIS set, so a TreeSet's own comparator decides. caturra
// asked the other set, so a case-insensitive TreeSet was unequal to a HashSet
// holding the same element in another case.
differential_test!(
    diff_tree_set_equals_uses_its_comparator,
    "DiffTreeSetEquals",
    r#"
import java.util.*;
public class DiffTreeSetEquals {
    public static void main(String[] args) {
        Comparator<String> ci = new Comparator<String>() {
            public int compare(String x, String y) { return x.compareToIgnoreCase(y); }
        };
        TreeSet<String> ts = new TreeSet<>(ci);
        ts.add("Apple");
        Set<String> hs = new HashSet<>(Arrays.asList("apple"));
        System.out.println("sizes: " + (ts.size() == hs.size()));
        System.out.println("containsAll: " + ts.containsAll(hs));
        System.out.println("equals: " + ts.equals(hs));
        TreeSet<String> plain = new TreeSet<>(Arrays.asList("a", "b"));
        System.out.println("plain: " + plain.equals(new HashSet<>(Arrays.asList("b", "a"))));
    }
}
"#
);

// Java 9's immutable factories. Their CONTENTS are well defined; the iteration
// ORDER of `Set.of`/`Map.of` is salted per JVM run in a real JDK, so only the
// ordered `List.of` can be compared as text.
differential_test!(
    diff_immutable_factories,
    "DiffImmutableOf",
    r#"
import java.util.*;
public class DiffImmutableOf {
    public static void main(String[] args) {
        List<String> l = List.of("a", "b");
        System.out.println(l + " " + l.equals(Arrays.asList("a", "b")) + " " + l.hashCode());
        try { l.add("c"); } catch (UnsupportedOperationException e) { System.out.println("immutable"); }
        try { List.of("a", (String) null); } catch (NullPointerException e) { System.out.println("NPE"); }
        Set<String> s = Set.of("x", "y");
        System.out.println(s.contains("x") + " " + s.size() + " " + s.equals(new HashSet<>(Arrays.asList("y", "x"))));
        try { Set.of("d", "d"); } catch (IllegalArgumentException e) { System.out.println(e.getMessage()); }
        Map<String, Integer> m = Map.of("k", 1);
        System.out.println(m.get("k") + " " + m.size() + " " + m.equals(Collections.singletonMap("k", 1)));
        try { m.put("j", 2); } catch (UnsupportedOperationException e) { System.out.println("map immutable"); }
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-9 cluster: interface members (JLS §9).
// ---------------------------------------------------------------------------

// `Iface.super.m()` — the standard way to pick one of several inherited
// defaults — did not parse at all. Plus `Class.isInterface()`/`getInterfaces()`
// and a cast to a PARAMETERIZED user interface, which casts by its erasure.
differential_test!(
    diff_interface_super_and_reflection,
    "DiffIfaceSuper",
    r#"
interface A { default String who() { return "A"; } }
interface B { default String who() { return "B"; } }
interface Marker { }
interface Sub extends Marker { default String d() { return "d"; } }
interface Gen<T> { default String g(T t) { return "G" + t; } }
class C implements A, B {
    public String who() { return A.super.who() + B.super.who(); }
}
class Impl implements Sub, Gen<String> { }
public class DiffIfaceSuper {
    public static void main(String[] args) {
        System.out.println(new C().who());
        System.out.println(Marker.class.isInterface() + " " + Impl.class.isInterface());
        System.out.println(Marker.class.getName());
        for (Class<?> c : Impl.class.getInterfaces()) System.out.println("i:" + c.getName());
        for (Class<?> c : Sub.class.getInterfaces()) System.out.println("s:" + c.getName());
        Object o = new Impl();
        System.out.println(((Sub) o).d());
        System.out.println(((Gen<String>) o).g("x"));
    }
}
"#
);

// javac: an implementation must be compatible with the interface method it
// implements — the same return type, no weaker access (including one INHERITED
// from a superclass), and no broader `throws`. caturra checked only the
// superclass chain, so each of these compiled and then ran the wrong body or
// aborted with an internal error.
differential_reject!(
    reject_interface_return_mismatch,
    "RejectIfaceReturn",
    r#"
interface I { String m(); }
class C implements I {
    public int m() { return 1; }
}
public class RejectIfaceReturn {
    public static void main(String[] args) { System.out.println("m=" + new C().m()); }
}
"#
);

differential_reject!(
    reject_interface_weaker_access,
    "RejectIfaceAccess",
    r#"
interface I { default String d() { return "I.d"; } }
class C implements I {
    private String d() { return "C.d"; }
}
public class RejectIfaceAccess {
    public static void main(String[] args) {
        I i = new C();
        System.out.println(i.d());
    }
}
"#
);

differential_reject!(
    reject_inherited_weaker_access,
    "RejectInheritedAccess",
    r#"
class Sup { String m() { return "Sup"; } }
interface I { default String m() { return "I"; } }
class C extends Sup implements I { }
public class RejectInheritedAccess {
    public static void main(String[] args) {
        I i = new C();
        System.out.println(i.m());
    }
}
"#
);

differential_reject!(
    reject_interface_broader_throws,
    "RejectIfaceThrows",
    r#"
interface I { default String risky() throws Exception { return "I"; } }
class Bad implements I {
    public String risky() throws Throwable { return "B"; }
}
public class RejectIfaceThrows {
    public static void main(String[] args) throws Exception {
        System.out.println(new Bad().risky());
    }
}
"#
);

// javac: a name inherited from BOTH a superclass and an interface is
// ambiguous — caturra folded the interface's constant and printed a value.
differential_reject!(
    reject_ambiguous_inherited_field,
    "RejectAmbiguousField",
    r#"
interface I { int K = 1; }
class Sup { int K = 2; }
class C extends Sup implements I {
    String show() { return "K=" + K; }
}
public class RejectAmbiguousField {
    public static void main(String[] args) { System.out.println(new C().show()); }
}
"#
);

// ---------------------------------------------------------------------------
// Round-9 cluster: StringBuilder as a reference type, and its own messages.
// ---------------------------------------------------------------------------

// A builder is an ordinary heap object, so it can be a collection's element, an
// array's element, and a generic type argument — each of which was refused with
// a message that was false about the program ("unknown type 'List'", "arrays are
// not yet supported"). It is also a CharSequence, so `new String(sb)` and
// `String.join(d, sb, sb)` take one, and it inherits Object's equals/hashCode.
differential_test!(
    diff_string_builder_as_a_reference,
    "DiffBuilderRef",
    r#"
import java.util.*;
public class DiffBuilderRef {
    static class Box<T> { T v; Box(T v) { this.v = v; } T get() { return v; } }
    public static void main(String[] args) {
        List<StringBuilder> l = new ArrayList<>();
        l.add(new StringBuilder("x"));
        System.out.println("size=" + l.size() + " first=" + l.get(0));
        StringBuilder[] arr = new StringBuilder[2];
        arr[0] = new StringBuilder("z");
        System.out.println("arr0=" + arr[0] + " arr1=" + arr[1]);
        System.out.println("toString=" + Arrays.toString(arr));
        arr[0].append("!");
        System.out.println("mutated=" + arr[0]);
        Box<StringBuilder> b = new Box<>(new StringBuilder("g"));
        System.out.println("len=" + b.get().length());
        StringBuilder a = new StringBuilder("abc");
        System.out.println(new String(a));
        System.out.println(String.join("-", a, new StringBuilder("z")));
        StringBuilder same = new StringBuilder("abc");
        System.out.println("equals=" + a.equals(same) + " self=" + a.equals(a));
        System.out.println("hashStable=" + (a.hashCode() == a.hashCode()));
        System.out.println("contains=" + l.contains(new StringBuilder("x")));
    }
}
"#
);

// The out-of-range messages, each recorded from a real JDK: a builder's
// `getChars` words the SOURCE failure as `start … end … length` and the
// DESTINATION one as a plain IndexOutOfBoundsException over the destination's
// range, while a STRING's `getChars` words the destination as `offset … count …
// length`; a builder's one-argument `substring` is `substring(start, count)`,
// so it reports the pair. A null destination is an ordinary NPE, not an
// internal abort.
differential_test!(
    diff_builder_range_messages,
    "DiffBuilderRanges",
    r#"
public class DiffBuilderRanges {
    public static void main(String[] args) {
        StringBuilder a = new StringBuilder("abcdef");
        char[] dst = new char[10];
        try { a.getChars(-1, 4, dst, 0); }
        catch (Throwable t) { System.out.println("src -1  -> " + t.getClass().getName() + ": " + t.getMessage()); }
        try { a.getChars(0, 6, dst, 8); }
        catch (Throwable t) { System.out.println("dst ovf -> " + t.getClass().getName() + ": " + t.getMessage()); }
        try { a.getChars(0, 2, dst, -1); }
        catch (Throwable t) { System.out.println("dst -1  -> " + t.getClass().getName() + ": " + t.getMessage()); }
        try { a.getChars(0, 2, null, 0); }
        catch (Throwable t) { System.out.println("gc null -> " + t.getClass().getName() + ": " + t.getMessage()); }
        String s = "abcdef";
        try { s.getChars(0, 6, dst, 8); }
        catch (Throwable t) { System.out.println("str dst -> " + t.getClass().getName() + ": " + t.getMessage()); }
        StringBuilder b = new StringBuilder("abc");
        try { b.substring(4); } catch (Throwable t) { System.out.println("sub(4)  -> " + t.getMessage()); }
        try { b.substring(-1); } catch (Throwable t) { System.out.println("sub(-1) -> " + t.getMessage()); }
        System.out.println("still alive");
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-9 cluster: modifiers and rare statements.
// ---------------------------------------------------------------------------

// Modifiers with no effect in a single-threaded VM are still ordinary Java a
// member may carry — `transient`, `volatile`, `synchronized`, `strictfp` — and
// used to make the whole member unparseable. So did `final` on an enhanced-for
// variable.
differential_test!(
    diff_inert_modifiers,
    "DiffInertModifiers",
    r#"
public class DiffInertModifiers {
    transient int t = 1;
    volatile int v = 2;
    strictfp double d() { return 1.0 / 4.0; }
    synchronized int s() { return 3; }
    static synchronized String shared() { return "shared"; }
    public static void main(String[] args) {
        DiffInertModifiers p = new DiffInertModifiers();
        System.out.println(p.t + " " + p.v + " " + p.d() + " " + p.s() + " " + shared());
        int[] a = { 1, 2, 3 };
        int sum = 0;
        for (final int x : a) sum += x;
        System.out.println("sum=" + sum);
        for (final String w : new String[] { "a", "b" }) System.out.print(w);
        System.out.println();
    }
}
"#
);

